import { useEffect, useState } from "react";
import { WeaponType, type AttackPowerType, type Weapon } from "../calculator/calculator.ts";
import { allEnemyTypes, type AmmoShots, type EnemyTypeRates } from "../calculator/weapon.ts";

export type AmmoClass = "arrow" | "greatarrow" | "bolt" | "ballistaBolt";

/**
 * One or more kinds of ammunition of the same class with identical damage, generated by
 * scripts/build_ammo_data.py
 */
export interface AmmoGroup {
  class: AmmoClass;
  names: string[];
  /** Base attack added to the weapon's, by damage type */
  attack: Partial<Record<AttackPowerType, number>>;
  /** Status buildup added to the weapon's */
  status: Partial<Record<AttackPowerType, number>>;
  /** Poise damage, which replaces the weapon's */
  poise?: number;
  /** Each shot's stamina cost, before the weapon's stamina rate */
  stamina?: number;
  /** Physical damage type, which replaces the weapon's */
  physicalType?: Weapon["ammoPhysicalType"];
  /** Damage multipliers against enemy types, e.g. Igon's Harpoon's ×1.3 against dragons */
  enemyTypeRates?: EnemyTypeRates;
  /** Bonuses for some weapons firing this, by weapon name */
  weaponBonuses?: Record<
    string,
    {
      /** Damage multipliers, e.g. the Lion Greatbow's ×1.2 physical for Radahn's Spears */
      damageMultipliers?: Partial<Record<AttackPowerType, number>>;
      /** More status buildup, e.g. the Serpent Bow's 15 poison for every arrow */
      status?: Partial<Record<AttackPowerType, number>>;
      /** Several bolts fired per shot, e.g. the Spread Crossbow's and Pulley Crossbow's three */
      shots?: AmmoShots;
    }
  >;
}

export const ammoClassLabels: Record<AmmoClass, string> = {
  arrow: "Arrows",
  greatarrow: "Greatarrows",
  bolt: "Bolts",
  ballistaBolt: "Ballista Bolts",
};

/** The ammunition each ranged weapon type uses */
export const weaponTypeAmmoClasses = new Map<WeaponType, AmmoClass>([
  [WeaponType.LIGHT_BOW, "arrow"],
  [WeaponType.BOW, "arrow"],
  [WeaponType.GREATBOW, "greatarrow"],
  [WeaponType.CROSSBOW, "bolt"],
  [WeaponType.BALLISTA, "ballistaBolt"],
]);

export function getAmmoKey(group: AmmoGroup) {
  return `${group.class}:${group.names.join("/")}`;
}

/**
 * @returns the names of the ammunition in a group, with any words they all end with written once,
 * e.g. "Piquebone / Rainbow Stone / Shattershard Arrow"
 */
export function getAmmoLabel({ names }: AmmoGroup) {
  const words = names.map((name) => name.split(" "));
  let common = 0;
  while (
    words.every((w) => w.length > common + 1) &&
    words.every((w) => w[w.length - 1 - common] === words[0][words[0].length - 1 - common])
  ) {
    common++;
  }
  if (names.length < 2 || common === 0) {
    return names.join(" / ");
  }
  const suffix = words[0].slice(-common).join(" ");
  return `${words.map((w) => w.slice(0, -common).join(" ")).join(" / ")} ${suffix}`;
}

/**
 * A ranged weapon firing the given ammunition. The ammunition's base attack and status buildup are
 * added to the weapon's at every upgrade level, and scaled by the weapon like its own, as is any
 * extra status buildup the weapon gives it. A damage bonus for the weapon multiplies damage after
 * enemy defenses, as tested in game.
 */
export function withAmmo(weapon: Weapon, group: AmmoGroup): Weapon {
  const bonus = group.weaponBonuses?.[weapon.weaponName];
  return {
    ...(bonus?.damageMultipliers && { damageMultipliers: bonus.damageMultipliers }),
    ...(group.poise != null && { ammoPoise: group.poise }),
    ammoNames: group.names,
    ...(group.stamina != null && { ammoStamina: group.stamina }),
    ...(bonus?.shots && { ammoShots: bonus.shots }),
    ...(group.physicalType && { ammoPhysicalType: group.physicalType }),
    ...weapon,
    name: `${weapon.name} (${getAmmoLabel(group)})`,
    // The ammunition's own multipliers against enemy types stack with the weapon's
    ...(group.enemyTypeRates && {
      enemyTypeRates: Object.fromEntries(
        allEnemyTypes.map((enemyType) => [
          enemyType,
          (group.enemyTypeRates?.[enemyType] ?? 1) * (weapon.enemyTypeRates?.[enemyType] ?? 1),
        ]),
      ),
    }),
    attack: weapon.attack.map((attack) => {
      const combined = { ...attack };
      const additions = [group.attack, group.status, bonus?.status ?? {}].flatMap((values) =>
        Object.entries(values),
      );
      for (const [type, value] of additions) {
        const attackPowerType = +type as AttackPowerType;
        combined[attackPowerType] = (combined[attackPowerType] ?? 0) + value!;
      }
      return combined;
    }),
  };
}

let ammoPromise: Promise<AmmoGroup[]> | undefined;

/**
 * Loads the ammunition data
 */
export default function useAmmo() {
  const [ammo, setAmmo] = useState<AmmoGroup[]>([]);
  useEffect(() => {
    ammoPromise ??= fetch("/ammo.json").then((res) => res.json());
    ammoPromise.then(setAmmo).catch(() => setAmmo([]));
  }, []);
  return ammo;
}
